subsection.content:
TYPE pointeur = ^ cellule ;

cellule = ENREGISTREMENT

  Champs 1 : Type 1 ;

  Champs 2 : Type 2 ;

  ...

  Champs N : Type N ;

  Suivant : pointeur ;

FIN ;

TYPE ptr_vehicule = ^ vehicule ;

vehicule = ENREGISTREMENT

  No_serie : Entier ;

  Prix : Réel ;

  Suivant : ptr_vehicule ;

FIN ;

Algorithme Création_liste :

ALGORITHME Création_liste ;

TYPE ptr_vehicule = ^ vehicule ;

vehicule = ENREGISTREMENT

  No_serie : Entier ;

  Prix : Réel ;

  Suivant : ptr_vehicule ;

FIN ;

VAR Tête, Courant : ptr_vehicule ;

Choix : Entier ;

DÉBUT

  ALLOUER(Tête) ;

  Courant <- Tête ;

  RÉPÉTER

    ÉCRIRE('Entrez le numéro de série du véhicule :') ;

    LIRE(Courant^.No_serie) ;

    ÉCRIRE('Entrez le prix du véhicule :') ;

    LIRE(Courant^.Prix) ;

    ÉCRIRE('Autre saisie ? 1. OUI 2. NON ') ;

    LIRE(Choix) ;

    SI (Choix = 1) ALORS

      ALLOUER(Courant^.Suivant) ;

      Courant <- Courant^.Suivant ;

    SINON

      Courant^.Suivant <- NIL ;

      Courant <- NIL ;

    FIN SI ;

  JUSQU'À (Choix = 2) ;

FIN.

Algorithme de consultation :

VAR Tête, Courant : ptr_vehicule ;

DÉBUT

  Courant <- Tête ;

  TANT QUE (Courant <> NIL) FAIRE

    ÉCRIRE(Courant^.No_serie, Courant^.Prix) ;

    Courant <- Courant^.Suivant ;

  FIN TANT QUE ;

FIN.

subsubsection.content:
VAR Tête, Nouveau : ptr_vehicule ;

DÉBUT

  {On suppose que la liste est créée avec l'algorithme "Création_liste"}

  ALLOUER(Nouveau) ;

  ÉCRIRE("Entrez le numéro de série du véhicule :") ;

  LIRE(Nouveau^.No_serie) ;

  ÉCRIRE("Entrez le prix du véhicule :") ;

  LIRE(Nouveau^.Prix) ;

  Nouveau^.Suivant <- Tête ;

  Tête <- Nouveau ;

  Nouveau <- NIL ;

FIN.

VAR Tête, Nouveau, Courant : ptr_vehicule ;

X : Entier ;

Trouve : Booléen ;

DÉBUT

  {On suppose que la liste est créée avec l'algorithme "Création_liste"}

  ALLOUER(Nouveau) ;

  ÉCRIRE("Entrez le numéro de série du véhicule :") ;

  LIRE(Nouveau^.No_serie) ;

  ÉCRIRE("Entrez le prix du véhicule :") ;

  LIRE(Nouveau^.Prix) ;

  Nouveau^.Suivant <- NIL ;

  ÉCRIRE("Donnez le numéro de série du véhicule qui précède le nouveau véhicule à insérer") ;

  LIRE(X) ;

  Courant <- Tête ;

  Trouve <- Faux ;

  TANT QUE (Courant <> NIL) ET (Trouve = Faux) FAIRE

    SI (Courant^.No_serie = X) ALORS

      Trouve <- Vrai ;

    SINON

      Courant <- Courant^.Suivant ;

    FIN SI ;

  FIN TANT QUE ;

  SI (Courant = NIL) ALORS

    ÉCRIRE("Le véhicule d'avant n'existe pas") ;

  SINON

    Nouveau^.Suivant <- Courant^.Suivant ;

    Courant^.Suivant <- Nouveau ;

    Nouveau <- NIL ;

    Courant <- NIL ;

  FIN SI ;

FIN.

VAR Tête, Nouveau, Courant : ptr_vehicule ;

DÉBUT

  {On suppose que la liste est créée par l'algorithme "Création_liste"}

  ALLOUER(Nouveau) ;

  ÉCRIRE("Entrez le numéro de série du véhicule :") ;

  LIRE(Nouveau^.No_serie) ;

  ÉCRIRE("Entrez le prix du véhicule :") ;

  LIRE(Nouveau^.Prix) ;

  Nouveau^.Suivant <- NIL ;

  Courant <- Tête ;

  TANT QUE (Courant^.Suivant <> NIL) FAIRE

    Courant <- Courant^.Suivant ;

  FIN TANT QUE ;

  Courant^.Suivant <- Nouveau ;

  Nouveau <- NIL ;

  Courant <- NIL ;

FIN.

VAR Tête, Temp : ptr_vehicule ;

DÉBUT

  {On suppose que la liste est créée par l'algorithme "Création_liste"}

  Temp <- Tête ; {Temp pointe vers la cellule à supprimer}

  ÉCRIRE('Donnez le numéro de série du véhicule à supprimer') ;

  LIRE(X) ;

  Trouve <- Faux ;

  TANT QUE (Temp <> NIL) ET (Trouve = Faux) FAIRE

    SI (Temp^.No_serie = X) ALORS

      Trouve <- Vrai ;

    SINON

      Temp <- Temp^.Suivant ;

    FIN SI ;

  FIN TANT QUE ;

  SI (Temp = NIL) ALORS

    ÉCRIRE('Le véhicule n'existe pas') ;

  SINON

    Courant <- Tête ; {Courant pointera sur la cellule précédente de la cellule à supprimer}

    TANT QUE (Courant^.Suivant <> Temp) FAIRE

      Courant <- Courant^.Suivant ;

    FIN TANT QUE ;

    Courant^.Suivant <- Temp^.Suivant ;

    LIBÉRER(Temp) ;

    Temp <- NIL ;

    Courant <- NIL ;

  FIN SI ;

FIN.

VAR Tête, Temp, Courant : ptr_vehicule ;

DÉBUT

  {On suppose que la liste est créée par l'algorithme "Création_liste"}

  Temp <- Tête ; {Temp pointera sur la cellule à supprimer}

  TANT QUE (Temp^.Suivant <> NIL) FAIRE

    Temp <- Temp^.Suivant ;

  FIN TANT QUE ;

  Courant <- Tête ; {Courant pointera sur la cellule précédente de la cellule à supprimer}

  TANT QUE (Courant^.Suivant <> Temp) FAIRE

    Courant <- Courant^.Suivant ;

  FIN TANT QUE ;

  Courant^.Suivant <- NIL ;

  LIBÉRER(Temp) ;

  Temp <- NIL ;

  Courant <- NIL ;

FIN.
